const page=await figma.getNodeByIdAsync('332:28013');await figma.setCurrentPageAsync(page);
await Promise.all(['Regular','Bold','Semibold'].map(style=>figma.loadFontAsync({family:'SF Pro',style})));
const vars=await figma.variables.getLocalVariablesAsync();
const vm=new Map(vars.filter(v=>v.variableCollectionId==='VariableCollectionId:334:26740'||v.variableCollectionId==='VariableCollectionId:334:26739').map(v=>[v.name,v]));
const styles=new Map((await figma.getLocalTextStylesAsync()).filter(s=>s.name.startsWith('V1/')).map(s=>[s.name,s]));
const roots=[], changed=[];
function paint(name){return figma.variables.setBoundVariableForPaint({type:'SOLID',color:{r:0,g:0,b:0}},'color',vm.get(name));}
function fill(n,name){n.fills=name?[paint(name)]:[];}
function stroke(n,name,w=1){n.strokes=[paint(name)];n.strokeWeight=w;}
function token(n,field,name){n.setBoundVariable(field,vm.get(name));}
function pad(n,size=12){for(const k of ['paddingLeft','paddingRight','paddingTop','paddingBottom'])token(n,k,'space/'+size);}
function gap(n,size=8){token(n,'itemSpacing','space/'+size);}
function frame(parent,name,w,h,dir='VERTICAL',bg=null){const n=figma.createAutoLayout(dir);parent.appendChild(n);n.name=name;n.resize(w,h);n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';fill(n,bg);return n;}
function comp(parent,name,w,h,dir='VERTICAL',bg=null){const n=figma.createComponent();parent.appendChild(n);n.name=name;n.resize(w,h);n.layoutMode=dir;n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';fill(n,bg);n.clipsContent=false;return n;}
async function text(parent,value,style='body',color='color/fg/default',width=null){const n=figma.createText();parent.appendChild(n);n.name=value.slice(0,35);n.fontName={family:'SF Pro',style:'Regular'};n.characters=value;await n.setTextStyleIdAsync(styles.get('V1/'+style).id);fill(n,color);if(width!==null){n.textAutoResize='HEIGHT';n.resize(width,20);}return n;}
function expose(c,n,name,def){const k=c.addComponentProperty(name,'TEXT',def);n.componentPropertyReferences={characters:k};return k;}
function bool(c,n,name,def=true){const k=c.addComponentProperty(name,'BOOLEAN',def);n.componentPropertyReferences={visible:k};}
async function instance(parent,id,name){const c=await figma.getNodeByIdAsync(id);const n=c.createInstance();parent.appendChild(n);if(name)n.name=name;return n;}
function props(n,values){for(const [prefix,v] of Object.entries(values)){const k=Object.keys(n.componentProperties).find(k=>k.split('#')[0]===prefix);if(k)n.setProperties({[k]:v});}}
async function icon(parent,name,size=16){const c=page.findOne(n=>n.type==='COMPONENT'&&n.name==='Icon / '+name);if(!c)throw Error('Missing icon '+name);const n=c.createInstance();parent.appendChild(n);n.resize(size,size);return n;}
async function button(parent,label,iconName=null){const n=await instance(parent,'336:26999');props(n,{label,leadingIcon:!!iconName});if(iconName){const c=page.findOne(n=>n.type==='COMPONENT'&&n.name==='Icon / '+iconName);props(n,{leadingIconSwap:c.id});}return n;}
async function iconButton(parent,name){const n=await instance(parent,'337:27399');const c=page.findOne(n=>n.type==='COMPONENT'&&n.name==='Icon / '+name);props(n,{icon:c.id});n.name='Icon Button / '+name;return n;}
async function badge(parent,label,tone='neutral'){const set=await figma.getNodeByIdAsync('376:32522');const c=set.children.find(n=>n.name==='tone='+tone+', appearance=subtle');const n=c.createInstance();parent.appendChild(n);props(n,{label});return n;}
function componentSet(parent,name,variants,desc,cols=3){const old=page.findOne(n=>n.type==='COMPONENT_SET'&&n.name===name);if(old)throw Error('Exists: '+name);const s=figma.combineAsVariants(variants,parent);s.name=name;s.description=desc;const w=Math.max(...variants.map(n=>n.width)),h=Math.max(...variants.map(n=>n.height));variants.forEach((n,i)=>{n.x=24+(i%cols)*(w+24);n.y=40+Math.floor(i/cols)*(h+30);});s.resize(Math.min(cols,variants.length)*(w+24)+24,Math.ceil(variants.length/cols)*(h+30)+40);return s;}
async function section(name,x,y,w,h){if(page.children.some(n=>n.name===name))throw Error('Exists '+name);const s=figma.createSection();page.appendChild(s);s.name=name;s.x=x;s.y=y;s.resizeWithoutConstraints(w,h);roots.push(s);return s;}
async function review(s,name,x,y,w,h,mode){const f=frame(s,name,w,h,'VERTICAL','color/content');f.x=x;f.y=y;pad(f,24);gap(f,16);f.setExplicitVariableModeForCollection(await figma.variables.getVariableCollectionByIdAsync('VariableCollectionId:334:26740'),mode);await text(f,name,'title-2');return f;}
function row(parent,w,h){const n=frame(parent,'Row',w,h,'HORIZONTAL');gap(n,12);n.counterAxisAlignItems='CENTER';return n;}
function absolute(n,x,y){n.layoutPositioning='ABSOLUTE';n.x=x;n.y=y;}
function vector(parent,name,path,w,h,color='color/fg/secondary',dash=null){const n=figma.createVector();parent.appendChild(n);n.name=name;n.vectorPaths=[{windingRule:'NONE',data:path}];n.resize(w,h);n.fills=[];stroke(n,color,1.5);n.strokeCap='ROUND';n.strokeJoin='ROUND';if(dash)n.dashPattern=dash;return n;}
function allIds(nodes){const a=[];function walk(n){a.push(n.id);if(n.type!=='INSTANCE'&&'children'in n)for(const c of n.children)walk(c);}nodes.forEach(walk);return [...new Set(a)];}

