async function iconButton(parent,name){const n=await instance(parent,'337:27399');const c=page.findOne(n=>n.type==='COMPONENT'&&n.name==='Icon / '+name);props(n,{icon:c.id});n.name='Icon Button / '+name;return n;}
async function badge(parent,label,tone='neutral'){const set=await figma.getNodeByIdAsync('376:32522');const c=set.children.find(n=>n.name==='tone='+tone+', appearance=subtle');const n=c.createInstance();parent.appendChild(n);props(n,{label});return n;}
function componentSet(parent,name,variants,desc,cols=3){const old=page.findOne(n=>n.type==='COMPONENT_SET'&&n.name===name);if(old)throw Error('Exists: '+name);const s=figma.combineAsVariants(variants,parent);s.name=name;s.description=desc;const w=Math.max(...variants.map(n=>n.width)),h=Math.max(...variants.map(n=>n.height));variants.forEach((n,i)=>{n.x=24+(i%cols)*(w+24);n.y=40+Math.floor(i/cols)*(h+30);});s.resize(Math.min(cols,variants.length)*(w+24)+24,Math.ceil(variants.length/cols)*(h+30)+40);return s;}
async function section(name,x,y,w,h){if(page.children.some(n=>n.name===name))throw Error('Exists '+name);const s=figma.createSection();page.appendChild(s);s.name=name;s.x=x;s.y=y;s.resizeWithoutConstraints(w,h);roots.push(s);return s;}
async function review(s,name,x,y,w,h,mode){const f=frame(s,name,w,h,'VERTICAL','color/content');f.x=x;f.y=y;pad(f,24);gap(f,16);f.setExplicitVariableModeForCollection(await figma.variables.getVariableCollectionByIdAsync('VariableCollectionId:334:26740'),mode);await text(f,name,'title-2');return f;}
function row(parent,w,h){const n=frame(parent,'Row',w,h,'HORIZONTAL');gap(n,12);n.counterAxisAlignItems='CENTER';return n;}
function absolute(n,x,y){n.layoutPositioning='ABSOLUTE';n.x=x;n.y=y;}
function vector(parent,name,path,w,h,color='color/fg/secondary',dash=null){const n=figma.createVector();parent.appendChild(n);n.name=name;n.vectorPaths=[{windingRule:'NONE',data:path}];n.resize(w,h);n.fills=[];stroke(n,color,1.5);n.strokeCap='ROUND';n.strokeJoin='ROUND';if(dash)n.dashPattern=dash;return n;}
function allIds(nodes){const a=[];function walk(n){a.push(n.id);if(n.type!=='INSTANCE'&&'children'in n)for(const c of n.children)walk(c);}nodes.forEach(walk);return [...new Set(a)];}

const drop=await figma.getNodeByIdAsync('445:38580');for(const id of ['445:38851','445:39111']){const p=await figma.getNodeByIdAsync(id);const found=[];for(const n of p.children){if(n.type==='INSTANCE'){const m=await n.getMainComponentAsync();if(m.parent.id===drop.id)found.push({n,state:m.name});}}const valid=found.find(x=>x.state==='state=insert').n,invalid=found.find(x=>x.state==='state=invalid').n;p.insertChild(p.children.indexOf(valid)+1,invalid);}
const gs=await figma.getNodeByIdAsync('447:40596'),ns=await figma.getNodeByIdAsync('447:39945'),es=await figma.getNodeByIdAsync('447:39952');
const endpoints=[],created=[],removed=[];
for(const c of gs.children.filter(n=>n.name.includes('state=ready'))){
 const canvas=c.children.find(n=>n.name==='Graph canvas'),pts=[],links=[];
 for(const n of canvas.children){if(n.type!=='INSTANCE')continue;const m=await n.getMainComponentAsync();if(m.parent.id===ns.id)pts.push(n);if(m.parent.id===es.id)links.push(n);}
 const a=pts.find(n=>n.componentProperties.state.value==='active'),targets=pts.filter(n=>n!==a&&n.componentProperties.state.value!=='isolated');
 for(let i=0;i<links.length;i++){const old=links[i],main=await old.getMainComponentAsync();const e=main.createInstance();canvas.insertChild(canvas.children.indexOf(old),e);created.push(e.id);removed.push(old.id);old.remove();const b=targets[i];let x1=a.x+a.width/2,y1=a.y+a.height/2,x2=b.x+b.width/2,y2=b.y+b.height/2;const dx=x2-x1,dy=y2-y1;const t1=Math.min(a.width/2/Math.abs(dx),a.height/2/Math.abs(dy)),t2=Math.min(b.width/2/Math.abs(dx),b.height/2/Math.abs(dy));x1+=dx*t1;y1+=dy*t1;x2-=dx*t2;y2-=dy*t2;const vx=x2-x1,vy=y2-y1,len=Math.sqrt(vx*vx+vy*vy),cos=vx/len,sin=vy/len;e.rescale(len/200);e.relativeTransform=[[cos,-sin,x1+sin*e.height/2],[sin,cos,y1-cos*e.height/2]];endpoints.push({id:e.id,width:e.width,lineWidth:e.children[0].width,expected:len});}
}
return {createdNodeIds:created,removedNodeIds:removed,mutatedNodeIds:['445:38851','445:39111',...allIds([gs])],endpoints};
